if(typeof requestAnimationFrame==='function'){let revealTries=0;const revealWindow=()=>{try{const pending=invoke('reveal_main_window');if(pending&&typeof pending.catch==='function')pending.catch(()=>{});}catch{}};const waitFirstPaint=()=>{if(document.getElementById('root')?.childElementCount){setTimeout(revealWindow,80);return;}if(++revealTries<40)requestAnimationFrame(waitFirstPaint);};requestAnimationFrame(waitFirstPaint);}


